<script setup lang="ts">
import { ref,nextTick,onMounted,onBeforeUnmount } from 'vue';
import { Terminal } from '@xterm/xterm';
import { FitAddon } from '@xterm/addon-fit';
import '@xterm/xterm/css/xterm.css';
import { api,errorText,socketUrl } from './api';
const props=defineProps<{projectId:string;workspaceRef:string;requirementId?:string;featureId?:string;autoOpen?:boolean;sessionKey?:string;sessionId?:string}>();
const emit=defineEmits<{error:[message:string];sessionStarted:[event:{key:string;id:string}]}>();
const attachedWorkspace=ref('');
const host=ref<HTMLDivElement>();const id=ref('');const state=ref('未開啟');const output=ref('');let terminal:Terminal|undefined,fit:FitAddon|undefined,ws:WebSocket|undefined,observer:ResizeObserver|undefined,reconnectTimer:ReturnType<typeof setTimeout>|undefined,reconnectAttempt=0,disposed=false,manuallyClosed=false;
function reportError(message:string){if(props.autoOpen&&terminal)terminal.write(`\r\n[terminal] ${message}\r\n`);else emit('error',message);}
function ensureTerminal(){if(terminal||!host.value)return;terminal=new Terminal({fontFamily:'Consolas, "Liberation Mono", monospace',fontSize:12,cursorBlink:true,theme:{background:'#15211f',foreground:'#c9ded1',cursor:'#99e5b5'},convertEol:true,scrollback:3000});fit=new FitAddon();terminal.loadAddon(fit);terminal.open(host.value);terminal.focus();fit.fit();terminal.onData(data=>send(data));observer=new ResizeObserver(resize);observer.observe(host.value);}
function disposeTerminal(){observer?.disconnect();observer=undefined;terminal?.dispose();terminal=undefined;fit=undefined;}
async function connect(){if(disposed||!id.value)return;state.value='連線中';const socket=new WebSocket(socketUrl(`/terminals/${encodeURIComponent(id.value)}`));ws=socket;socket.onopen=()=>{reconnectAttempt=0;state.value='running';resize();terminal?.focus();};socket.onmessage=event=>{let message:any;try{message=JSON.parse(event.data);}catch{message={type:'terminal.output',data:String(event.data)};}if(message.type==='terminal.output'||message.type==='output'){const data=message.data??message.payload?.data??'';terminal?.write(data);output.value=(output.value+data).slice(-100000);}if(message.type==='terminal.exited'||message.type==='exit'){state.value=`exited (${message.exitCode??message.payload?.exitCode??'?'})`;manuallyClosed=true;}if(message.type==='error')reportError(message.message??'終端執行失敗');};socket.onclose=event=>{if(ws===socket)ws=undefined;if(disposed||manuallyClosed)return;if(event.code===1008){id.value='';void open();return;}state.value='重連中';const delay=Math.min(10000,500*Math.pow(2,reconnectAttempt++));reconnectTimer=setTimeout(()=>void connect(),delay);};socket.onerror=()=>{state.value='重連中';};}
async function attach(result:{id:string;workspaceRef?:string}){if(id.value&&id.value!==result.id)close();if(id.value===result.id)return;attachedWorkspace.value=result.workspaceRef??props.workspaceRef;try{id.value=result.id;manuallyClosed=false;await nextTick();if(disposed)return;ensureTerminal();if(!terminal||!fit)throw Error('終端畫面尚未就緒');fit.fit();await connect();}catch(error){state.value='error';reportError(errorText(error));}}
async function open(){if(id.value)return;state.value='開啟中';try{const result=await api('/terminals',{projectId:props.projectId,sessionKey:props.sessionKey??props.projectId,requirementId:props.requirementId,featureId:props.featureId,workspaceRef:props.workspaceRef,cols:100,rows:24});if(props.autoOpen)emit('sessionStarted',{key:props.sessionKey??'',id:result.id});if(disposed)return;await attach(result);}catch(error){state.value='error';reportError(errorText(error));}}
defineExpose({attach});
function send(data:string){if(ws?.readyState!==WebSocket.OPEN){reportError('終端尚未連線，輸入未送出');return;}ws.send(JSON.stringify({type:'input',data}));}
function resize(){if(!fit||!terminal)return;fit.fit();if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'resize',cols:terminal.cols,rows:terminal.rows}));}
function close(){manuallyClosed=true;if(reconnectTimer)clearTimeout(reconnectTimer);if(id.value)void api(`/terminals/${encodeURIComponent(id.value)}`,undefined,'DELETE').catch(error=>reportError(errorText(error)));ws?.close();ws=undefined;disposeTerminal();id.value='';state.value='closed';}
onMounted(async()=>{if(!props.autoOpen)return;await nextTick();if(disposed)return;ensureTerminal();if(props.sessionId){await attach({id:props.sessionId,workspaceRef:props.workspaceRef});return;}try{const saved=await api<{id:string|null}>(`/projects/${encodeURIComponent(props.projectId)}/terminal-session?key=${encodeURIComponent(props.sessionKey??props.projectId)}`);if(disposed)return;if(saved.id)await attach({id:saved.id,workspaceRef:props.workspaceRef});else await open();}catch(error){state.value='error';reportError(errorText(error));}});
onBeforeUnmount(()=>{disposed=true;if(reconnectTimer)clearTimeout(reconnectTimer);ws?.close();ws=undefined;disposeTerminal();});
</script>
<template><section :class="autoOpen?'terminal-only':'panel terminal-panel'"><div v-if="!autoOpen" class="panel-heading"><div><span class="eyebrow">WORKSPACE / PTY</span><h2>專案終端機</h2></div><div class="button-row"><span class="tag">{{state}}</span><button v-if="id" class="button small" @click="close">關閉</button><button v-if="!id" data-testid="open-terminal" class="button small" @click="open">開啟終端</button></div></div><div v-if="!autoOpen" class="terminal-location"><span class="mono">{{attachedWorkspace||workspaceRef||'未指定 workspace'}}</span><span data-testid="terminal-session-id" class="mono">{{id}}</span></div><div v-show="autoOpen||id" ref="host" data-testid="xterm-host" class="xterm-host"></div><p v-if="!autoOpen&&!id" class="empty-small">開啟後連接工作區內的實際 PTY 程序。</p><details v-if="!autoOpen&&id" class="output-log"><summary>文字輸出紀錄</summary><pre data-testid="terminal-output">{{output}}</pre></details></section></template>
